import { clsx, type ClassValue } from "clsx"
import { twMerge } from "tailwind-merge"

const formatter = new Intl.NumberFormat("vi-VN", {
  style: "currency",
  currency: "VND",
  maximumFractionDigits: 0,
})

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs))
}

export function formatVND(value: number) {
  return formatter.format(value)
}

function apiOrigin() {
  const apiUrl = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8001/api"

  try {
    return new URL(apiUrl).origin
  } catch {
    return "http://localhost:8001"
  }
}

export function productImageUrl(image?: string | null) {
  if (!image) {
    return "/images/NoImage.jpg"
  }

  if (image.startsWith("http://") || image.startsWith("https://")) {
    try {
      const url = new URL(image)

      if (url.pathname.startsWith("/storage/")) {
        return `${apiOrigin()}/api/product-images/${url.pathname.replace(/^\/storage\//, "")}${url.search}`
      }

      if (url.pathname.startsWith("/api/product-images/")) {
        return `${apiOrigin()}${url.pathname}${url.search}`
      }
    } catch {
      return image
    }

    return image
  }

  if (image.startsWith("data:") || image.startsWith("/images/")) {
    return image
  }

  if (image.startsWith("/storage/")) {
    return `${apiOrigin()}/api/product-images/${image.replace(/^\/storage\//, "")}`
  }

  if (image.startsWith("storage/")) {
    return `${apiOrigin()}/api/product-images/${image.replace(/^storage\//, "")}`
  }

  return `${apiOrigin()}/api/product-images/${image.replace(/^\/+/, "")}`
}
